-- One row per device or person. Ids are generated by the server and act as bearer secrets.
create table subscriptions (
  id text primary key,
  created_at timestamptz not null
);

-- Ways to reach a subscription. `address` is the push endpoint (later: email address, Telegram chat id),
-- and each address belongs to one subscription only.
create table channels (
  subscription_id text not null references subscriptions (id) on delete cascade,
  kind text not null,
  address text not null,
  data jsonb not null default '{}',
  primary key (kind, address)
);
create index channels_subscription on channels (subscription_id);

create table areas (
  id text primary key,
  subscription_id text not null references subscriptions (id) on delete cascade,
  position smallint not null,
  label text not null,
  lon double precision not null,
  lat double precision not null,
  radius_km double precision not null,
  hazards text[] not null,
  min_alert text not null
);
create index areas_subscription on areas (subscription_id, position);

-- The highest alert level each area has been sent per event, so it is only alerted again on escalation.
create table notified (
  area_id text not null references areas (id) on delete cascade,
  event_key text not null,
  level text not null,
  at timestamptz not null,
  primary key (area_id, event_key)
);
create index notified_at on notified (at);
